+		struct sockaddr_in *addr = (struct sockaddr_in *)&address_range->addr;
+		struct sockaddr_in *mask = (struct sockaddr_in *)&address_range->mask;
+		in_addr_t client_addr = sin->sin_addr.s_addr;
